fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let n = s.len();
    let mut result: Vec<Vec<char>> = Vec::with_capacity(n);

    for i in 0..n {
        // prefix is s[0..=i]
        result.push(s[..=i].to_vec());
    }

    result
}